export function parseRange(input: string): number[] {
  if (typeof input !== 'string') throw new TypeError('input must be a string');
  const parts = input.split('-').map(Number);
  if (parts.length !== 2) throw new Error('range must have exactly two bounds');
  const [start, end] = parts;
  if (Number.isNaN(start) || Number.isNaN(end)) throw new Error('invalid range bounds');
  if (start > end) throw new RangeError('start must be <= end');
  const out: number[] = [];
  for (let i = start; i <= end; i++) out.push(i);
  return out;
}
